using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using OCRS.Models;
namespace OCRS.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin")] public class UsersController(UserManager<ApplicationUser> users):Controller { public async Task<IActionResult> Index(string? q,string? role){var x=users.Users.AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(u=>u.FullName.Contains(q)||u.Email!.Contains(q));var list=await x.OrderBy(u=>u.FullName).ToListAsync();if(!string.IsNullOrWhiteSpace(role)){var ids=(await users.GetUsersInRoleAsync(role)).Select(u=>u.Id).ToHashSet();list=list.Where(u=>ids.Contains(u.Id)).ToList();}ViewBag.Role=role;return View(list);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Toggle(string id){var u=await users.FindByIdAsync(id);if(u==null)return NotFound();if(await users.IsInRoleAsync(u,"Admin")&&u.IsActive&&(await users.GetUsersInRoleAsync("Admin")).Count(x=>x.IsActive)<=1){TempData["Error"]="Không thể vô hiệu hóa quản trị viên cuối cùng.";return RedirectToAction(nameof(Index));}u.IsActive=!u.IsActive;u.LockoutEnd=u.IsActive?null:DateTimeOffset.MaxValue;await users.UpdateAsync(u);return RedirectToAction(nameof(Index));} }
